    con = sqlite3.connect(DB_PATH)
    con.execute("PRAGMA busy_timeout = 30000;")
    cur = con.cursor()
    
    pose_paths = {}
    for pose, src_path in IMAGES[handle].items():
        if not os.path.exists(src_path):
            print(f"[-] Error: Source image for {handle} {pose} not found at {src_path}")
            continue
            
        dst_path = f"{avatar_dir}/{handle}_{pose}.png"
        shutil.copy2(src_path, dst_path)
        pose_paths[pose] = dst_path
        print(f"[+] Staged pose {pose} at {dst_path}")
        
        # Also copy avatar for general fallback
        if pose == "avatar":
            shutil.copy2(src_path, f"{avatar_dir}/avatar.png")
            shutil.copy2(src_path, f"{avatar_dir}/{handle}.png")
            shutil.copy2(src_path, f"{avatar_dir}/{handle}_avatar.png")
            
    # 2. Register in sys_media_asset and cmdb_ci_media_asset
    for pose, filepath in pose_paths.items():
        size = os.path.getsize(filepath)
        md5_h = get_md5(filepath)
        sha_h = get_sha256(filepath)
        
        with open(filepath, "rb") as f:
            b64_data = base64.b64encode(f.read()).decode("utf-8")
            
        # sys_media_asset
        cur.execute("SELECT sys_id FROM sys_media_asset WHERE file_path = ?", (filepath,))
        existing_sys = cur.fetchone()
        
        asset_name = f"{display_name} {pose.capitalize()}"
        file_name = os.path.basename(filepath)
        
        if existing_sys:
            sys_id = existing_sys[0]
            print(f"[~] Updating sys_media_asset for {asset_name}")
            cur.execute("""
                UPDATE sys_media_asset
                SET name = ?, file_size_bytes = ?, md5_hash = ?, image_blob = ?, updated_at = datetime('now'), sys_updated_on = CURRENT_TIMESTAMP
                WHERE sys_id = ?
            """, (asset_name, size, md5_h, b64_data, sys_id))
        else:
            sys_id = uuid.uuid4().hex
            tag = generate_next_asset_tag(cur)
            print(f"[+] Inserting sys_media_asset for {asset_name} with tag {tag}")
            cur.execute("""
                INSERT INTO sys_media_asset (sys_id, asset_tag, name, file_name, file_path, file_size_bytes, mime_type, category, status, md5_hash, image_blob, created_at, updated_at, sys_created_on, sys_updated_on)
                VALUES (?, ?, ?, ?, ?, ?, 'image/png', 'FanStack Avatars', 'Active', ?, ?, datetime('now'), datetime('now'), CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
            """, (sys_id, tag, asset_name, file_name, filepath, size, md5_h, b64_data))
            
        # cmdb_ci_media_asset
        web_path = f"/avatars/{handle}/{file_name}"
        cur.execute("SELECT sys_id FROM cmdb_ci_media_asset WHERE advocate = ? AND expression = ?", (handle, pose))
        existing_cmdb = cur.fetchone()
        
        if existing_cmdb:
            print(f"[~] Updating cmdb_ci_media_asset expression={pose}")
            cur.execute("""
                UPDATE cmdb_ci_media_asset
                SET file_path = ?, sha256 = ?, sys_updated_on = CURRENT_TIMESTAMP
                WHERE sys_id = ?
            """, (web_path, sha_h, existing_cmdb[0]))
        else:
            print(f"[+] Inserting cmdb_ci_media_asset expression={pose}")
            cur.execute("""
                INSERT INTO cmdb_ci_media_asset (sys_id, advocate, expression, file_path, sha256, sys_created_on, sys_updated_on)
                VALUES (?, ?, ?, ?, ?, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
            """, (uuid.uuid4().hex, handle, pose, web_path, sha_h))

    # Get avatar base64 for persona.avatar_blob
